funcao relacaoEhVerdadeira(painel) {
  var partes = []

  se (painel.inclui("=")) {
    partes = painel.dividir("=")
    retorna numero(partes[0]) == numero(partes[1])
  }

  se (painel.inclui(">")) {
    partes = painel.dividir(">")
    retorna numero(partes[0]) > numero(partes[1])
  }

  partes = painel.dividir("<")
  retorna numero(partes[0]) < numero(partes[1])
}

